export function queueQuery(s){const searching=!!s.search.trim();return {queue:searching?'':s.bucket==='selected'?'selected':s.bucket==='archive'?'archive':'review',bucket:searching||['selected','archive'].includes(s.bucket)?'':s.bucket,direction:searching?'':s.direction,q:s.search,owner:s.ownerFilter||'',offset:s.offset||0};}
const fields=['name','city','language','directions','portfolio','profile','views','followers','experience','availabilityDays','audienceKz','adult','closeup','terms','consent'];
const formValue=a=>({...a,portfolio:Array.isArray(a.portfolio)?a.portfolio.join('\n'):a.portfolio||''});
const same=(a,b)=>JSON.stringify(a??'')===JSON.stringify(b??'');
export function beginCandidateEdit(a){return {editing:true,editingId:a.id,editingVersion:a.version,editingBase:formValue(a),draft:formValue(a),editingConflict:false};}
export function candidateChanges(base,draft){return fields.filter(k=>!same(formValue(base||{})[k],formValue(draft||{})[k]));}
export function rebaseCandidateEdit(base,draft,current){const next=formValue(current);for(const key of candidateChanges(base,draft))next[key]=draft[key];return {...beginCandidateEdit(current),draft:next};}
export const editableCandidate=a=>a&&['review','clarification','reserve'].includes(a.status);
export const blankPost=()=>({text:'',includeForm:true,scheduledAt:'',dirty:false});
export function editPost(p){return {id:p.id,version:p.version||1,text:p.text,includeForm:false,scheduledAt:p.scheduledAt?new Date(new Date(p.scheduledAt)-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'',dirty:false};}
export function aiStateText(e={}){return ({pending:'ИИ: в очереди',queued:'ИИ: в очереди',running:'ИИ: оценивает',quota:'ИИ: ждём обновления квоты',unavailable:'ИИ недоступен · можно выбрать вручную',disabled:'Отбор по правилам',not_configured:'Отбор по правилам',stale:'Оценка обновляется'})[e.aiStatus]||'';}
export function assessmentLabels(a){const labels={recommended:'Подходит для просмотра',recommend:'Подходит для просмотра',clarify:'Нужно уточнить',pass:'Не рекомендован'};return (a.directions||[]).map(key=>{const outcome=a.evaluation?.ai?.directions?.[key]?.recommendation||a.evaluation?.ai?.directions?.[key]||a.evaluation?.[key];return {key,label:key==='ugc'?'UGC':'Охваты',outcome,text:labels[outcome]||'Нужен просмотр'};});}
export function captureInteraction(root){if(!root)return null;const doc=root.ownerDocument,active=doc.activeElement,focus=root.contains(active)?active:null;return {values:[...root.querySelectorAll('input,textarea,select')].map(el=>({name:el.name,form:el.closest('form')?.dataset.form,value:el.value})),scroll:root.querySelector('.drawer-scroll')?.scrollTop||0,open:[...root.querySelectorAll('details')].map((el,index)=>({key:el.dataset.section||String(index),open:el.open})),focus:focus?{id:focus.id,name:focus.name,form:focus.closest('form')?.dataset.form,section:focus.closest('details')?.dataset.section,start:focus.selectionStart,end:focus.selectionEnd}:null};}
export function restoreInteraction(root,snapshot){if(!snapshot)return;const scroll=root.querySelector('.drawer-scroll');if(scroll)scroll.scrollTop=snapshot.scroll;[...root.querySelectorAll('details')].forEach((el,index)=>{const old=snapshot.open.find(v=>v.key===(el.dataset.section||String(index)));if(old)el.open=old.open;});const f=snapshot.focus;if(!f)return;const field=[...root.querySelectorAll('input,textarea,select,button,a,summary')].find(el=>f.id?el.id===f.id:f.name?el.name===f.name&&el.closest('form')?.dataset.form===f.form:f.section?el.tagName==='SUMMARY'&&el.closest('details')?.dataset.section===f.section:false);if(field){field.focus({preventScroll:true});if(typeof f.start==='number'&&field.setSelectionRange)field.setSelectionRange(f.start,f.end);}}
